#define KERNEL0 (g_weights + 0)
#define BIAS0   (g_weights + 5120)
#define KERNEL1 (g_weights + 5248)
#define BIAS1   (g_weights + 21632)
#define KERNEL2 (g_weights + 21760)
#define BIAS2   (g_weights + 22272)

void policyForward(const float obs[POLICY_OBS_DIM], float actionOut[POLICY_ACTION_DIM])
{
  float h0[128];
  for (int j = 0; j < 128; j++) {
    float acc = BIAS0[j];
    for (int k = 0; k < 40; k++) {
      acc += obs[k] * KERNEL0[k * 128 + j];
    }
    h0[j] = tanhf(acc);
  }
  float h1[128];
  for (int j = 0; j < 128; j++) {
    float acc = BIAS1[j];
    for (int k = 0; k < 128; k++) {
      acc += h0[k] * KERNEL1[k * 128 + j];
    }
    h1[j] = tanhf(acc);
  }
  for (int j = 0; j < 4; j++) {
    float acc = BIAS2[j];
    for (int k = 0; k < 128; k++) {
      acc += h1[k] * KERNEL2[k * 4 + j];
    }
    actionOut[j] = acc;
  }
}
